{"query":"command line suggestion list overlay renderBody layoutOnce fitHeight header render","repo_root":"/home/anthoni/projects/workspace-entire/anthnel/devdesk","commit":"7c8fe3fcf67ac6fc10785bd5cf4ac409b9b415ac","tree":"ba5239d57586733a4c2aabbda5bcea30fa20584d","profile":"full","results":[{"rank":1,"score":98.2952,"file_path":"internal/app/view.go","start_line":28,"end_line":109,"focus_line":36,"snippet_start_line":36,"snippet_end_line":109,"symbol_start_line":36,"symbol_end_line":64,"language":"Go","kind":"function","symbol_id":"local/devdesk:Go:internal/app/view.go:function:fitHeight","symbol_name":"fitHeight","qualified_name":"fitHeight","signature":"func fitHeight(header, body, footer string, height int) string","signals":["body","exact-symbol","symbol-name","signature","constraint:entity","constraint:phrase","constraint:relationship","exact-code-token","graph:callers","complete-symbol","contiguous-span"],"snippet":"func fitHeight(header, body, footer string, height int) string {
	parts := []string{header}
	if body != "" {
		parts = append(parts, body)
	}
	if footer != "" {
		parts = append(parts, footer)
	}
	lines := strings.Split(strings.Join(parts, "\n"), "\n")
	excess := len(lines) - height
	if height <= 0 || excess <= 0 {
		return strings.Join(lines, "\n")
	}

	headerLen := strings.Count(header, "\n") + 1
	bodyLen := 0
	if body != "" {
		bodyLen = strings.Count(body, "\n") + 1
	}
	cut := min(excess, bodyLen)
	if cut > 0 {
		end := headerLen + bodyLen
		lines = append(lines[:end-cut], lines[end:]...)
	}
	if len(lines) > height {
		lines = lines[:height]
	}
	return strings.Join(lines, "\n")
}

// activeOverlay returns the overlay to draw instead of the view, or "" when
// there is none. The order matches the one handleKeyMsg dispatches in, so the
// overlay holding the keyboard is the one on screen.
func (a *App) activeOverlay() string {
	switch {
	case a.switchingTo != "":
		return a.renderContextSwitchingOverlay()
	case a.showHelp:
		return a.renderHelpOverlay()
	case a.showContextList:
		return a.renderContextListOverlay()
	}
	return ""
}

// renderBody fills the viewport with the active view's content, padded to the
// full inner width so no line shows the terminal's own background (Rule 115).
func (a *App) renderBody() string {
	content := "View not found: " + string(a.currentView)
	if view, ok := a.views[a.currentView]; ok {
		content = view.View()
	}

	innerWidth := a.viewport.Width - 2 // -2 for the borders
	if a.frameless() {
		innerWidth = a.viewport.Width
	}
	a.viewport.SetContent(lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorText).
		Width(innerWidth).
		Render(content))

	body := a.viewport.View()

	// Rule 136: with a filter bar below it, the viewport's bottom corners become
	// T-junctions so the two form one closed rectangle.
	if view, ok := a.views[a.currentView]; ok {
		if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
			body = replaceViewportBottomCorners(body)
		}
	}
	return a.overlaySuggestions(body)
}","merged_ranks":[1,3]},{"rank":2,"score":95.0729,"file_path":"internal/app/app.go","start_line":343,"end_line":383,"focus_line":347,"snippet_start_line":347,"snippet_end_line":383,"symbol_start_line":347,"symbol_end_line":373,"language":"Go","kind":"method","symbol_id":"local/devdesk:Go:internal/app/app.go:method:App.layoutOnce","symbol_name":"layoutOnce","qualified_name":"App.layoutOnce","signature":"func (a *App) layoutOnce(width, height int) (changed bool)","signals":["body","exact-symbol","symbol-name","signature","constraint:entity","exact-code-token","graph:callers","complete-symbol","contiguous-span"],"snippet":"func (a *App) layoutOnce(width, height int) (changed bool) {
	// Rule 124: footer height is deducted from the viewport (tabs + optional info line)
	footerHeight := a.getFooterHeight()
	a.lastFooterHeight = footerHeight

	headerHeight := lipgloss.Height(a.renderHeader())
	availableHeight := height - headerHeight - footerHeight
	a.viewport.Width = width
	a.viewport.Height = availableHeight - 1 // -1 for the custom title border line

	// Propagate to the active view. The viewport has 1 border (bottom only),
	// the view must know the inner height. A frameless view has none and
	// reclaims the line.
	viewportBorderHeight := 1
	a.viewport.Style = viewportStyle()
	if a.frameless() {
		viewportBorderHeight = 0
		a.viewport.Style = framelessViewportStyle()
	}
	contentHeight := max((availableHeight-1)-viewportBorderHeight, 1)
	if view, ok := a.views[a.currentView]; ok {
		updatedView, _ := view.Update(tea.WindowSizeMsg{Width: width, Height: contentHeight})
		a.views[a.currentView] = updatedView
	}

	return a.getFooterHeight() != footerHeight
}

