1	package app
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/anthnel/devdesk/internal/command"
8		"github.com/anthnel/devdesk/internal/ui/cmdsuggest"
9	)
10	
11	// minListHeight is the smallest usable viewport height that holds a list: one
12	// row and the bottom rule.
13	const minListHeight = 2
14	
15	// noticeEmptyLine is the warning for an enter on a line with nothing typed.
16	const noticeEmptyLine = "Type a name or choose one"
17	
18	// refreshSuggestions ranks the registry for the text in the command line. The
19	// first row is highlighted when a query is typed (a bare ":" is none) and
20	// something is found; otherwise nothing is, so enter cannot run a command nobody chose.
21	func (a *App) refreshSuggestions() {
22		a.suggestions = a.suggester.Suggest(a.commandInput.Value())
23		a.sugOffset = 0
24		a.sugCursor = -1
25		if a.argStage() {
26			a.sugCursor = a.defaultArgCursor()
27			return
28		}
29		if a.suggestions.Query != "" && len(a.suggestions.Entries) > 0 {
30			a.sugCursor = 0
31		}
32	}
33	
34	// refreshSuggestionsKeepCursor recomputes the list after an asynchronous load
35	// without undoing a move the user already made: the cursor stays where it was,
36	// bounded to the new number of rows.
37	func (a *App) refreshSuggestionsKeepCursor() {
38		cursor, offset := a.sugCursor, a.sugOffset
39		a.refreshSuggestions()
40		if cursor < 0 || a.sugCursor < 0 {
41			return
42		}
43		a.sugCursor = min(cursor, a.listRowCount()-1)
44		a.sugOffset = max(min(offset, a.sugCursor), 0)
45	}
46	
47	// resetSuggestions forgets the list; the command line is closed or about to be
48	// reopened empty.
49	func (a *App) resetSuggestions() {
50		a.suggestions = command.Suggestions{}
51		a.sugCursor = -1
52		a.sugOffset = 0
53		a.sugNotice = ""
54	}
55	
56	// highlightedEntry returns the highlighted row, if there is one. With no list
57	// drawn there is no highlight: a choice nobody can see is never made.
58	func (a *App) highlightedEntry() (command.Entry, bool) {
59		if a.listVisible() == 0 || a.sugCursor < 0 || a.sugCursor >= len(a.suggestions.Entries) {
60			return command.Entry{}, false
61		}
62		return a.suggestions.Entries[a.sugCursor], true
63	}
64	
65	// canComplete reports whether tab has something to complete: a highlighted
66	// row, at the command stage (an argument is typed, not chosen).
67	func (a *App) canComplete() bool {
68		if a.argStage() {
69			return a.listVisible() > 0 && len(a.suggestions.Args) > 0
70		}
71		_, ok := a.highlightedEntry()
72		return ok && a.suggestions.Stage == command.StageCommand
73	}
74	
75	// nothingToRunNotice is the warning for an enter with no highlighted row.
76	func (a *App) nothingToRunNotice() string {
77		q := a.suggestions.Query
78		if q == "" {
79			return noticeEmptyLine
80		}
81		return fmt.Sprintf("%q is not a view or a command", q)
82	}
83	
84	// completeHighlighted writes the highlighted row's name into the line, with a
85	// trailing space when the command takes an argument. It runs nothing.
86	func (a *App) completeHighlighted() {
87		if a.argStage() {
88			a.completeArg()
89			return
90		}
91		if !a.canComplete() {
92			return
93		}
94		entry, _ := a.highlightedEntry()
95		text := entry.Name
96		if entry.TakesArg() {
97			text += " "
98		}
99		a.commandInput.SetValue(text)
100		a.commandInput.CursorEnd()
101		a.refreshSuggestions()
102	}
103	
104	// listUsable is the number of viewport content lines the list may cover.
105	func (a *App) listUsable() int {
106		if a.frameless() {
107			return a.viewport.Height
108		}
109		return a.viewport.Height - 1 // the bottom border stays
110	}
111	
112	// listVisible is how many suggestion rows are drawn; 0 means no list.
113	func (a *App) listVisible() int {
114		usable := a.listUsable()
115		if usable < minListHeight {
116			return 0
117		}
118		return cmdsuggest.VisibleRows(a.listRowCount(), usable)
119	}
120	
121	// moveHighlight moves the highlight by delta rows without wrapping. With no
122	// highlighted row, down takes the first visible row and up the last.
123	func (a *App) moveHighlight(delta int) {
124		n := a.listRowCount()
125		if n == 0 {
126			return
127		}
128		visible := a.listVisible()
129		switch {
130		case a.sugCursor < 0 && delta > 0:
131			a.sugCursor = a.sugOffset
132		case a.sugCursor < 0:
133			a.sugCursor = min(n-1, a.sugOffset+max(visible, 1)-1)
134		default:
135			a.sugCursor = max(min(a.sugCursor+delta, n-1), 0)
136		}
137		a.sugOffset = cmdsuggest.Window(a.sugCursor, a.sugOffset, visible)
138	}
139	
140	// keepHighlightVisible re-windows the list after the viewport changed size.
141	func (a *App) keepHighlightVisible() {
142		a.sugOffset = cmdsuggest.Window(a.sugCursor, a.sugOffset, a.listVisible())
143	}
144	
145	// suggestionLines renders the list and its bottom rule, or nil when the command
146	// line is closed or the viewport is too short for a list.
147	func (a *App) suggestionLines() []string {
148		visible := a.listVisible()
149		if !a.commandMode || visible == 0 {
150			return nil
151		}
152		rows := a.entryRows()
153		var heading, empty string
154		var loading bool
155		if a.argStage() {
156			rows = a.argRows()
157			heading, empty = a.argHeading(), a.argEmpty()
158			loading = !a.suggestions.ArgsReady
159		}
160		frame := cmdsuggest.FrameJoined
161		if a.frameless() {
162			frame = cmdsuggest.FrameClosed
163		}
164		return cmdsuggest.Render(cmdsuggest.Input{
165			Rows:    rows,
166			Total:   a.suggestions.Total,
167			Query:   a.suggestions.Query,
168			Cursor:  a.sugCursor,
169			Offset:  a.sugOffset,
170			Notice:  a.sugNotice,
171			Heading: heading,
172			Empty:   empty,
173			Loading: loading,
174			Width:   a.viewport.Width,
175			Visible: visible,
176			Frame:   frame,
177		})
178	}
179	
180	// entryRows renders the command-stage suggestions as list rows.
181	func (a *App) entryRows() []cmdsuggest.Row {
182		rows := make([]cmdsuggest.Row, len(a.suggestions.Entries))
183		for i, e := range a.suggestions.Entries {
184			rows[i] = cmdsuggest.Row{Entry: e, Current: e.Kind == command.KindView && e.Name == string(a.currentView)}
185		}
186		return rows
187	}
188	
189	// overlaySuggestions replaces the top lines of the viewport with the list.
190	// Whole lines are swapped, so no styled text is ever cut.
191	func (a *App) overlaySuggestions(body string) string {
192		list := a.suggestionLines()
193		if len(list) == 0 {
194			return body
195		}
196		lines := strings.Split(body, "\n")
197		copy(lines, list)
198		return strings.Join(lines, "\n")
199	}
