1	// Package cmdsuggest renders the command-suggestion list shown under the
2	// command line (DEVDESK-89). Rendering is pure: state in, lines out.
3	package cmdsuggest
4	
5	import (
6		"fmt"
7		"strings"
8	
9		"github.com/charmbracelet/lipgloss"
10		"github.com/charmbracelet/x/ansi"
11	
12		"github.com/anthnel/devdesk/internal/command"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// MaxVisibleRows is the ceiling on suggestion rows shown at once.
17	const MaxVisibleRows = 8
18	
19	// Row is one suggestion; Current marks the view that is open now.
20	type Row struct {
21		Entry   command.Entry
22		Current bool
23		// Arg, when non-nil, makes this an argument row: Entry is ignored.
24		Arg *command.ArgSuggestion
25	}
26	
27	// Frame selects the corners of the bottom rule.
28	type Frame int
29	
30	const (
31		// FrameJoined draws ├─┤ (the list sits above more viewport content).
32		FrameJoined Frame = iota
33		// FrameClosed draws └─┘.
34		FrameClosed
35	)
36	
37	// Input is everything Render needs.
38	type Input struct {
39		Rows   []Row
40		Total  int
41		Query  string
42		Cursor int // -1 means no highlighted row
43		Offset int
44		Notice string
45		// Heading replaces the "N of M" count in the filet (argument stage).
46		Heading string
47		// Empty is the message shown when there are no rows and Loading is false.
48		Empty string
49		// Loading shows "Loading contexts…" in place of the rows.
50		Loading bool
51		Width   int
52		Visible int
53		Frame   Frame
54	}
55	
56	// Layout holds column widths in cells.
57	type Layout struct{ Marker, Name, Alias, Desc int }
58	
59	// Pair is a foreground/background combination the list paints.
60	type Pair struct {
61		Name   string
62		Fg, Bg lipgloss.Color
63	}
64	
65	// Layout constants, in cells. The widths below are the whole grid: a line is
66	// a border, a one-cell margin, the columns, then fill up to the other border.
67	const (
68		margin        = 1
69		markerWidth   = 2
70		minDescWidth  = 20
71		minAliasWidth = 34 // narrowest terminal that still shows the alias column
72		wideWidth     = 100
73		aliasSep      = " · "
74		currentTag    = "(current)"
75		ellipsis      = "…"
76		// minNoteWidth is the narrowest note column worth drawing; below it the
77		// note disappears before the name or the (current) tag lose a cell.
78		minNoteWidth = 8
79		loadingText  = "Loading contexts…"
80		// minRenderWidth is the narrowest width that holds a frame, a margin, a
81		// marker and one name cell.
82		minRenderWidth = 6
83	)
84	
85	// VisibleRows returns how many list rows fit: the matches, at least one row
86	// (the "no match" line), capped by MaxVisibleRows and by the usable height
87	// minus the filet.
88	func VisibleRows(matches, usable int) int {
89		return max(min(max(matches, 1), MaxVisibleRows, usable-1), 0)
90	}
91	
92	// Window returns the first visible row so that cursor stays in view. The
93	// window never wraps and, with no highlighted row, keeps the current offset.
94	func Window(cursor, offset, visible int) int {
95		offset = max(offset, 0)
96		if cursor < 0 || visible <= 0 {
97			return offset
98		}
99		switch {
100		case cursor < offset:
101			return cursor
102		case cursor >= offset+visible:
103			return cursor - visible + 1
104		}
105		return offset
106	}
107	
108	// Columns returns the column widths for a terminal width. Columns leave from
109	// the right: description first, then alias; the name alone remains.
110	func Columns(width int) Layout {
111		l := Layout{Marker: markerWidth}
112		if width < minAliasWidth {
113			l.Name = max(width-6, 1)
114			return l
115		}
116		l.Name, l.Alias = 15, 14
117		if width >= wideWidth {
118			l.Name, l.Alias = 18, 18
119		}
120		if desc := width - 2 - margin - l.Marker - l.Name - l.Alias; desc >= minDescWidth {
121			l.Desc = desc
122		}
123		return l
124	}
125	
126	// first returns the index of the first row drawn, kept inside the list.
127	func first(in Input) int {
128		return max(min(in.Offset, len(in.Rows)-max(in.Visible, 0)), 0)
129	}
130	
131	// FiletLabel returns the text of the bottom rule: the notice as a warning
132	// when there is one, otherwise the count with what scrolled out of view.
133	func FiletLabel(in Input) string {
134		if in.Notice != "" {
135			return theme.IconWarning + " " + in.Notice
136		}
137		in.Visible = max(in.Visible, 0)
138		label := fmt.Sprintf("%d of %d", len(in.Rows), in.Total)
139		switch {
140		case in.Heading != "":
141			label = in.Heading
142		case strings.TrimSpace(in.Query) == "":
143			label = fmt.Sprintf("%d available", len(in.Rows))
144		}
145		start := first(in)
146		if above := start; above > 0 {
147			label += fmt.Sprintf(" · ▲ %d more", above)
148		}
149		if below := len(in.Rows) - start - in.Visible; below > 0 {
150			label += fmt.Sprintf(" · ▼ %d more", below)
151		}
152		return label
153	}
154	
155	// look is one foreground/background combination, read from the theme at call
156	// time so that a theme applied after start-up is honored.
157	type look struct {
158		name string
159		fg   lipgloss.Color
160		bg   lipgloss.Color
161		bold bool
162	}
163	
164	func (k look) style() lipgloss.Style {
165		return lipgloss.NewStyle().Foreground(k.fg).Background(k.bg).Bold(k.bold)
166	}
167	
168	func rowLook() look {
169		return look{name: "row", fg: theme.ColorText, bg: theme.ColorBackground}
170	}
171	
172	func highlightLook() look {
173		return look{name: "highlighted row", fg: theme.ColorText, bg: theme.ColorTableLineSelected, bold: true}
174	}
175	
176	func argNoteLook() look {
177		return look{name: "argument note", fg: theme.ColorText, bg: theme.ColorBackground}
178	}
179	
180	func highlightedArgNoteLook() look {
181		return look{name: "highlighted argument note", fg: theme.ColorText, bg: theme.ColorTableLineSelected}
182	}
183	
184	func messageLook() look {
185		return look{name: "message", fg: theme.ColorText, bg: theme.ColorBackground}
186	}
187	
188	func filetLook() look {
189		return look{name: "filet label", fg: theme.ColorText, bg: theme.ColorBackground}
190	}
191	
192	func warningLook() look {
193		return look{name: "filet warning", fg: theme.ColorFooterWarn, bg: theme.ColorBackground, bold: true}
194	}
195	
196	// Palette lists every text pair the list paints, for the contrast test. The
197	// frame characters are decoration and carry no information, so they are not
198	// listed.
199	func Palette() []Pair {
200		var out []Pair
201		for _, k := range []look{rowLook(), highlightLook(), argNoteLook(), highlightedArgNoteLook(), messageLook(), filetLook(), warningLook()} {
202			out = append(out, Pair{Name: k.name, Fg: k.fg, Bg: k.bg})
203		}
204		return out
205	}
206	
207	// Render returns Visible list rows followed by the bottom rule, each exactly
208	// Width cells wide. Every line is assembled from separately styled segments;
209	// no already-styled text is ever cut.
210	func Render(in Input) []string {
211		in.Visible = max(in.Visible, 0)
212		if in.Width < minRenderWidth {
213			return degenerate(in)
214		}
215		inner := max(in.Width-2, 0)
216		layout := Columns(in.Width)
217		border := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
218		side := border.Render("│")
219	
220		lines := make([]string, 0, in.Visible+1)
221		if len(in.Rows) == 0 {
222			for i := 0; i < in.Visible; i++ {
223				body := theme.EmptyLineBg(inner)
224				if i == 0 {
225					body = row(emptyText(in), layout, inner, false)
226				}
227				lines = append(lines, side+body+side)
228			}
229		} else {
230			start := first(in)
231			for i := 0; i < in.Visible; i++ {
232				idx := start + i
233				if idx >= len(in.Rows) {
234					lines = append(lines, side+theme.EmptyLineBg(inner)+side)
235					continue
236				}
237				lines = append(lines, side+row(columnsOf(in.Rows[idx], layout, inner), layout, inner, idx == in.Cursor)+side)
238			}
239		}
240		return append(lines, filet(in, inner, border))
241	}
242	
243	// degenerate renders the lines of a terminal too narrow for a frame: blank
244	// background lines and a bare rule, each exactly Width cells (possibly zero).
245	func degenerate(in Input) []string {
246		w := max(in.Width, 0)
247		lines := make([]string, 0, in.Visible+1)
248		for i := 0; i < in.Visible; i++ {
249			lines = append(lines, theme.EmptyLineBg(w))
250		}
251		rule := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
252		return append(lines, rule.Render(strings.Repeat("─", w)))
253	}
254	
255	// cells is the plain text of each column of one row.
256	// A message spans every column.
257	type cells struct {
258		name, alias, desc, message string
259		// arg marks an argument row: name and desc arrive already fitted.
260		arg bool
261	}
262	
263	// emptyText returns the message of a list with no rows: loading wins, then the
264	// caller's own wording, then the command stage's "No match".
265	func emptyText(in Input) cells {
266		switch {
267		case in.Loading:
268			return cells{message: loadingText}
269		case in.Empty != "":
270			return cells{message: in.Empty}
271		}
272		return cells{message: fmt.Sprintf("No match for %q", in.Query)}
273	}
274	
275	// columnsOf returns the plain text of a row for a layout. The current marker
276	// leads the description, or stands in for the aliases when the description
277	// is hidden; it is dropped when neither column exists.
278	func columnsOf(r Row, l Layout, inner int) cells {
279		if r.Arg != nil {
280			return argCells(r, l, inner)
281		}
282		c := cells{
283			name:  r.Entry.Label(),
284			alias: strings.Join(r.Entry.Aliases, aliasSep),
285			desc:  r.Entry.Description,
286		}
287		if r.Current {
288			switch {
289			case l.Desc > 0:
290				c.desc = strings.TrimSpace(currentTag + " " + c.desc)
291			case l.Alias > 0:
292				c.alias = currentTag
293			}
294		}
295		return c
296	}
297	
298	// fit truncates plain text to leave one cell of air inside its column and
299	// pads it to the full width.
300	func fit(text string, width int) string {
301		if width <= 0 {
302			return ""
303		}
304		if lipgloss.Width(text) > width-1 {
305			text = ansi.Truncate(text, max(width-1, 1), ellipsis)
306		}
307		return text + strings.Repeat(" ", max(width-lipgloss.Width(text), 0))
308	}
309	
310	// argCells lays out an argument row: the value, then " (current)" glued to
311	// it, then the note. A long value gives way first, and the note disappears
312	// before either. The tag is kept whole only while the row has room for it
313	// (about 12 cells and more); below that the final fit() cuts the line.
314	func argCells(r Row, l Layout, inner int) cells {
315		avail := max(inner-margin-markerWidth, 0)
316		text := r.Arg.Value
317		if r.Current {
318			tag := " " + currentTag
319			if room := avail - lipgloss.Width(tag) - 1; lipgloss.Width(text) > room {
320				text = ansi.Truncate(text, max(room, 1), ellipsis)
321			}
322			text += tag
323		}
324		nameCol := min(max(lipgloss.Width(text)+1, l.Name), avail)
325		c := cells{name: fit(text, nameCol), arg: true}
326		if noteW := avail - nameCol; r.Arg.Note != "" && noteW >= minNoteWidth {
327			c.desc = fit(r.Arg.Note, noteW)
328		}
329		return c
330	}
331	
332	// row assembles one list line from styled segments, filled up to inner cells.
333	// A highlighted row fills with its own background so it reaches the border.
334	func row(c cells, l Layout, inner int, highlighted bool) string {
335		k, note, marker := rowLook(), argNoteLook(), strings.Repeat(" ", markerWidth)
336		if highlighted {
337			k, note, marker = highlightLook(), highlightedArgNoteLook(), theme.IconCircleSmall+" "
338		}
339		if c.message != "" {
340			k = messageLook()
341			marker = strings.Repeat(" ", markerWidth)
342		}
343		if c.arg {
344			return argLine(c, inner, k, note, marker)
345		}
346		body := fit(c.name, l.Name) + fit(c.alias, l.Alias) + fit(c.desc, l.Desc)
347		if c.message != "" {
348			body = fit(c.message, max(inner-margin-markerWidth, 0))
349		}
350		return k.style().Render(padTo(strings.Repeat(" ", margin)+marker+body, inner))
351	}
352	
353	// argLine renders an argument row as two segments, the name and the note, so
354	// the note can carry its own look.
355	func argLine(c cells, inner int, k, note look, marker string) string {
356		head := strings.Repeat(" ", margin) + marker + c.name
357		if c.desc == "" {
358			return k.style().Render(padTo(head, inner))
359		}
360		return k.style().Render(head) + note.style().Render(padTo(c.desc, inner-lipgloss.Width(head)))
361	}
362	
363	// padTo pads plain text with spaces up to width cells.
364	func padTo(plain string, width int) string {
365		return plain + strings.Repeat(" ", max(width-lipgloss.Width(plain), 0))
366	}
367	
368	// filet builds the bottom rule with its label.
369	func filet(in Input, inner int, border lipgloss.Style) string {
370		left, right := "├", "┤"
371		if in.Frame == FrameClosed {
372			left, right = "└", "┘"
373		}
374		k := filetLook()
375		if in.Notice != "" {
376			k = warningLook()
377		}
378		label := ansi.Truncate(FiletLabel(in), max(inner-3, 0), ellipsis)
379		dashes := max(inner-2-lipgloss.Width(label)-1, 0)
380		return border.Render(left+"─ ") + k.style().Render(label) +
381			border.Render(" "+strings.Repeat("─", dashes)+right)
382	}
