1	package app
2	
3	import (
4		"strings"
5	
6		"github.com/charmbracelet/lipgloss"
7	
8		"github.com/anthnel/devdesk/internal/ui/theme"
9	)
10	
11	// View renders the interface: header, title line, viewport, footer (Rule 124).
12	// An open overlay replaces the whole thing.
13	func (a *App) View() string {
14		if overlay := a.activeOverlay(); overlay != "" {
15			return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
16				lipgloss.WithWhitespaceBackground(theme.ColorBackground))
17		}
18	
19		header := a.renderHeader() + "\n" + a.renderTitleLine()
20		body := a.renderBody()
21		footer := a.renderViewFooter()
22		inner := fitHeight(header, body, footer, a.height)
23	
24		return lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
25			lipgloss.WithWhitespaceBackground(theme.ColorBackground))
26	}
27	
28	// fitHeight stacks header, body and footer in at most height lines.
29	// lipgloss.Place pads a short block but never crops a tall one, so on a very
30	// small terminal (header 10 + title 1 + the viewport's minimum + footer) the
31	// frame would be taller than the screen. The surplus is taken from the body
32	// first, bottom lines first: the header carries the command line and the
33	// footer carries the messages, so both outrank viewport rows. If the header
34	// alone is taller than the terminal, the whole stack is cut to its first
35	// height lines, the simplest floor. At normal heights nothing is cut.
36	func fitHeight(header, body, footer string, height int) string {
37		parts := []string{header}
38		if body != "" {
39			parts = append(parts, body)
40		}
41		if footer != "" {
42			parts = append(parts, footer)
43		}
44		lines := strings.Split(strings.Join(parts, "\n"), "\n")
45		excess := len(lines) - height
46		if height <= 0 || excess <= 0 {
47			return strings.Join(lines, "\n")
48		}
49	
50		headerLen := strings.Count(header, "\n") + 1
51		bodyLen := 0
52		if body != "" {
53			bodyLen = strings.Count(body, "\n") + 1
54		}
55		cut := min(excess, bodyLen)
56		if cut > 0 {
57			end := headerLen + bodyLen
58			lines = append(lines[:end-cut], lines[end:]...)
59		}
60		if len(lines) > height {
61			lines = lines[:height]
62		}
63		return strings.Join(lines, "\n")
64	}
65	
66	// activeOverlay returns the overlay to draw instead of the view, or "" when
67	// there is none. The order matches the one handleKeyMsg dispatches in, so the
68	// overlay holding the keyboard is the one on screen.
69	func (a *App) activeOverlay() string {
70		switch {
71		case a.switchingTo != "":
72			return a.renderContextSwitchingOverlay()
73		case a.showHelp:
74			return a.renderHelpOverlay()
75		case a.showContextList:
76			return a.renderContextListOverlay()
77		}
78		return ""
79	}
80	
81	// renderBody fills the viewport with the active view's content, padded to the
82	// full inner width so no line shows the terminal's own background (Rule 115).
83	func (a *App) renderBody() string {
84		content := "View not found: " + string(a.currentView)
85		if view, ok := a.views[a.currentView]; ok {
86			content = view.View()
87		}
88	
89		innerWidth := a.viewport.Width - 2 // -2 for the borders
90		if a.frameless() {
91			innerWidth = a.viewport.Width
92		}
93		a.viewport.SetContent(lipgloss.NewStyle().
94			Background(theme.ColorBackground).
95			Foreground(theme.ColorText).
96			Width(innerWidth).
97			Render(content))
98	
99		body := a.viewport.View()
100	
101		// Rule 136: with a filter bar below it, the viewport's bottom corners become
102		// T-junctions so the two form one closed rectangle.
103		if view, ok := a.views[a.currentView]; ok {
104			if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
105				body = replaceViewportBottomCorners(body)
106			}
107		}
108		return a.overlaySuggestions(body)
109	}
110	
111	// renderTitleLine draws the viewport's top border carrying the view's title —
112	// or, for a frameless view, a titled rule with no corners: GetTitle() keeps a
113	// reader oriented where a top border would draw the top of a nonexistent box.
114	func (a *App) renderTitleLine() string {
115		title := ""
116		if view, ok := a.views[a.currentView]; ok {
117			if hv, implements := view.(HeaderView); implements {
118				title = hv.GetTitle()
119			}
120		}
121		if a.frameless() {
122			return theme.RenderTitledRule(title, a.width)
123		}
124		return theme.RenderBorderTitle(title, a.width)
125	}
126	
127	// frameless reports whether the active view draws its own frames (see
128	// FramelessView). The default is framed.
129	func (a *App) frameless() bool {
130		view, ok := a.views[a.currentView]
131		if !ok {
132			return false
133		}
134		fv, implements := view.(FramelessView)
135		return implements && fv.Frameless()
136	}
137	
138	// renderViewFooter returns the active view's footer, or "" when it has none.
139	func (a *App) renderViewFooter() string {
140		if view, ok := a.views[a.currentView]; ok {
141			if fv, ok := view.(FooterView); ok {
142				return fv.RenderFooter(a.width)
143			}
144		}
145		return ""
146	}
147	
148	// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
149	// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
150	// the border into one closed rectangle instead of two stacked boxes.
151	func replaceViewportBottomCorners(body string) string {
152		lastNewline := strings.LastIndex(body, "\n")
153		if lastNewline == -1 {
154			return body
155		}
156		lastLine := body[lastNewline+1:]
157		lastLine = strings.Replace(lastLine, "└", "├", 1)
158		lastLine = strings.Replace(lastLine, "┘", "┤", 1)
159		return body[:lastNewline+1] + lastLine
160	}
