package app

import (
	"strings"

	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
	"github.com/charmbracelet/lipgloss"
)

// HeaderView is the interface each view must implement to provide the header data
type HeaderView interface {
	GetShortcuts() shortcut.Shortcuts
	GetTitle() string
	GetIcon() string
	GetHeaderInfo(context string) []shortcut.HeaderInfo
}

// FooterView is implemented by views that have footer content rendered below the viewport border (Rule 124).
// The footer can contain a tab bar (1 line) and optionally an empty line + info line (2 lines).
type FooterView interface {
	GetFooterHeight() int          // current footer height in lines (0 if no footer)
	RenderFooter(width int) string // rendered footer content
}

// FramelessView is implemented by a view that draws its own frames and wants
// none around it. The default — framed — is the safe behavior: a view that
// does not implement this is framed like all the others, unlike HeaderView
// whose missing half silently renders an empty title.
//
// Only one view implements it (the dashboard), and that is deliberate: every
// other view frames a single object — a table, a form.
type FramelessView interface {
	Frameless() bool
}

// headerMinHeight is the fixed header height (without the command line).
const headerMinHeight = 7

// ASCII logo for the header
var logoLines = []string{
	`    ____            ____            __  `,
	`   / __ \___ _   __/ __ \___  _____/ /__`,
	`  / / / / _ \ | / / / / / _ \/ ___/ //_/`,
	` / /_/ /  __/ |/ / /_/ /  __(__  ) ,<   `,
	`/_____/\___/|___/_____/\___/____/_/|_|  `,
}

const logoWidth = 40 // max width of a logo line

// renderHeader generates the header (fixed height) followed by the command line (1 line).
func (a *App) renderHeader() string {
	if view, ok := a.views[a.currentView]; ok {
		if headerView, implementsHeaderView := view.(HeaderView); implementsHeaderView {
			shortcuts := headerView.GetShortcuts()
			if a.commandMode {
				shortcuts = a.commandLineShortcuts()
			}
			info := headerView.GetHeaderInfo(a.currentContext)

			header := renderHeaderContent(info, shortcuts, a.width)

			pad := theme.Bg(" ")
			var cmdLine string
			if a.commandMode {
				cmdLine = pad + theme.CommandLineStyle.Width(a.width-2).Render(a.commandInput.View()) + pad
			} else {
				cmdLine = pad + theme.CommandLineInactiveStyle.Width(a.width-2).Render("❯") + pad
			}

			// A blank line under the command line keeps it from touching the title rule.
			return header + "\n" + theme.EmptyLineBg(a.width) + "\n" + cmdLine + "\n" + theme.EmptyLineBg(a.width)
		}
	}

	return ""
}

// renderHeaderContent generates the header block with a fixed height (headerMinHeight).
// Layout: 3 columns — info (25%), shortcuts (flexible), logo (fixed width).
func renderHeaderContent(info []shortcut.HeaderInfo, shortcuts shortcut.Shortcuts, width int) string {
	// Two padding cells are the minimum a row can hold; below that the header
	// is blank rather than wider than the window.
	if width < 2 {
		return strings.Join(blankHeaderRows(width), "\n")
	}
	innerWidth := width - 2 // 1 padding each side

	// Column widths
	col1Width := innerWidth / 4
	col3Width := logoWidth
	// The logo column is fixed-width: drop it when it cannot sit next to the
	// info column, rather than pushing every row past the window (Rule 108).
	if innerWidth < col1Width+logoWidth {
		col3Width = 0
	}
	col2Width := innerWidth - col1Width - col3Width
	if col2Width < 0 {
		col2Width = 0
	}

	// Build column 1: key-value info lines
	col1Lines := buildInfoLines(info, col1Width)

	// Build column 2: shortcuts
	col2Lines := buildShortcutLines(shortcuts, col2Width)

	// Build column 3: logo (centered vertically — 1 empty line on top since 6 logo lines / 7 header lines)
	var col3Lines []string
	if col3Width > 0 {
		col3Lines = buildLogoLines(col3Width)
	}

	// Assemble rows
	rows := make([]string, headerMinHeight)
	for i := 0; i < headerMinHeight; i++ {
		c1 := ""
		if i < len(col1Lines) {
			c1 = col1Lines[i]
		}
		c2 := ""
		if i < len(col2Lines) {
			c2 = col2Lines[i]
		}
		c3 := ""
		if i < len(col3Lines) {
			c3 = col3Lines[i]
		}

		pad := theme.Bg(" ")
		row := pad + theme.PadWithBg(c1, col1Width) + theme.PadWithBg(c2, col2Width) + theme.PadWithBg(c3, col3Width) + pad
		rows[i] = row
	}

	return strings.Join(rows, "\n")
}

// blankHeaderRows returns headerMinHeight background-filled rows of the given width.
func blankHeaderRows(width int) []string {
	rows := make([]string, headerMinHeight)
	for i := range rows {
		rows[i] = theme.EmptyLineBg(width)
	}
	return rows
}

// buildInfoLines builds the key-value info lines for column 1, aligning values on the longest key.
// Lines wider than col1Width are clipped, so a narrow column never overflows into the next one.
func buildInfoLines(info []shortcut.HeaderInfo, col1Width int) []string {
	// Find max key length for alignment
	maxKeyLen := 0
	for _, h := range info {
		if len(h.Key) > maxKeyLen {
			maxKeyLen = len(h.Key)
		}
	}

	lines := make([]string, headerMinHeight)
	for i := 0; i < headerMinHeight; i++ {
		if i < len(info) {
			// Pad key to maxKeyLen so all ": " align
			paddedKey := info[i].Key + strings.Repeat(" ", maxKeyLen-len(info[i].Key))
			label := theme.HeaderKeyStyle.Render(paddedKey + ": ")

			value := info[i].Value
			if info[i].Style.GetForeground() != lipgloss.Color("") {
				value = info[i].Style.Background(theme.ColorBackground).Render(value)
			} else {
				value = lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Render(value)
			}

			lines[i] = label + value
			if col1Width > 0 {
				// MaxWidth truncates on rune boundaries and keeps escape sequences intact.
				lines[i] = lipgloss.NewStyle().MaxWidth(col1Width).Render(lines[i])
			} else {
				// No room at all: show nothing rather than overflow.
				lines[i] = ""
			}
		} else {
			lines[i] = ""
		}
	}
	return lines
}

// buildShortcutLines builds the shortcut lines for column 2
func buildShortcutLines(shortcuts shortcut.Shortcuts, col2Width int) []string {
	// A column with no width shows no shortcut: PadWithBg returns a long line
	// untouched, so anything rendered here would spill past the window.
	if len(shortcuts) == 0 || col2Width <= 0 {
		lines := make([]string, headerMinHeight)
		for i := range lines {
			lines[i] = ""
		}
		return lines
	}

	// Split shortcuts into columns of maxLine items
	columns := splitArrayIntoChunks(shortcuts, headerMinHeight)

	// Get rendered lines for each column
	var allColumnLines [][]string
	for i, col := range columns {
		minH := 0
		if i == 0 {
			minH = headerMinHeight
		}
		allColumnLines = append(allColumnLines, renderShortcutsColumnLines(col, minH))
	}

	// Normalize heights
	for i := range allColumnLines {
		for len(allColumnLines[i]) < headerMinHeight {
			allColumnLines[i] = append(allColumnLines[i], "")
		}
	}

	// Calculate column widths
	colWidths := make([]int, len(allColumnLines))
	for ci, colLines := range allColumnLines {
		for _, line := range colLines {
			if w := lipgloss.Width(line); w > colWidths[ci] {
				colWidths[ci] = w
			}
		}
	}

	sep := "  "
	sepRendered := theme.Bg(sep)

	// Build each row
	result := make([]string, headerMinHeight)
	for row := 0; row < headerMinHeight; row++ {
		var line string
		for ci, colLines := range allColumnLines {
			if ci > 0 {
				line += sepRendered
			}
			if row < len(colLines) {
				line += theme.PadWithBg(colLines[row], colWidths[ci])
			} else {
				line += theme.EmptyLineBg(colWidths[ci])
			}
		}
		// Clip to the column. PadWithBg cannot do this — it pads a short line and
		// returns a long one untouched — and a plain slice would cut an escape
		// sequence in half, which is the hazard Rule 122 is about. MaxWidth
		// truncates on rune boundaries and leaves the sequences intact.
		if col2Width > 0 {
			line = lipgloss.NewStyle().MaxWidth(col2Width).Render(line)
		}
		result[row] = line
	}

	return result
}

// buildLogoLines builds the logo lines for column 3, vertically centered
func buildLogoLines(col3Width int) []string {
	logoStyle := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorPrimary).
		Bold(true)

	lines := make([]string, headerMinHeight)
	// 5 logo lines in 7 header lines → 1 empty line top and bottom
	offset := 1
	for i := 0; i < headerMinHeight; i++ {
		logoIdx := i - offset
		if logoIdx >= 0 && logoIdx < len(logoLines) {
			lines[i] = theme.PadWithBg(logoStyle.Render(logoLines[logoIdx]), col3Width)
		} else {
			lines[i] = theme.EmptyLineBg(col3Width)
		}
	}
	return lines
}

// renderShortcutsColumnLines renders a column of shortcuts as individual lines padded to the same width with background.
func renderShortcutsColumnLines(shortcuts shortcut.Shortcuts, minHeight int) []string {
	if len(shortcuts) == 0 {
		return nil
	}

	lines := shortcuts.ToStrings()

	// Find max width for uniform padding
	maxWidth := 0
	for _, line := range lines {
		if w := lipgloss.Width(line); w > maxWidth {
			maxWidth = w
		}
	}

	// Pad each line to the same width with background
	var result []string
	for _, line := range lines {
		result = append(result, theme.PadWithBg(line, maxWidth))
	}

	// Add empty lines if minHeight required
	for len(result) < minHeight {
		result = append(result, theme.EmptyLineBg(maxWidth))
	}

	return result
}

func splitArrayIntoChunks(arr []shortcut.Shortcut, chunkSize int) []shortcut.Shortcuts {
	var chunks []shortcut.Shortcuts
	for i := 0; i < len(arr); i += chunkSize {
		end := i + chunkSize
		if end > len(arr) {
			end = len(arr)
		}
		chunks = append(chunks, arr[i:end])
	}
	return chunks
}

// commandLineShortcuts is the header's vocabulary while the command line owns
// the keyboard. It replaces the view's own: tab and enter stay in place and
// grey out when no row is highlighted (Rule 130).
func (a *App) commandLineShortcuts() shortcut.Shortcuts {
	_, runnable := a.runnableText()
	return shortcut.Shortcuts{
		{Key: "↑↓", Description: "Choose"},
		{Key: "tab", Description: "Complete", Disabled: !a.canComplete()},
		{Key: "enter", Description: "Open", Disabled: !runnable},
		{Key: "esc", Description: "Close"},
	}
}

package app

import (
	"log"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/ui/about"
	"github.com/anthnel/devdesk/internal/ui/agentusageview"
	"github.com/anthnel/devdesk/internal/ui/configuration"
	"github.com/anthnel/devdesk/internal/ui/containers"
	"github.com/anthnel/devdesk/internal/ui/dashboard"
	"github.com/anthnel/devdesk/internal/ui/filebrowser"
	"github.com/anthnel/devdesk/internal/ui/forge/auth"
	"github.com/anthnel/devdesk/internal/ui/forge/explorer"
	"github.com/anthnel/devdesk/internal/ui/jobsview"
	"github.com/anthnel/devdesk/internal/ui/netdiag"
	ociresources "github.com/anthnel/devdesk/internal/ui/oci_resources"
	"github.com/anthnel/devdesk/internal/ui/security"
	"github.com/anthnel/devdesk/internal/ui/status"
	"github.com/anthnel/devdesk/internal/ui/templates"
	uiviewer "github.com/anthnel/devdesk/internal/ui/viewer"
	"github.com/anthnel/devdesk/internal/ui/workspaces"
)

// handleCommandMode handles a key while the command line owns the keyboard.
// Every key first clears the warning on the list's bottom rule: it lasts until
// the next keystroke, with no timer.
func (a *App) handleCommandMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	a.sugNotice = ""

	switch msg.Type {
	case tea.KeyEsc:
		return a, a.closeCommandLine()
	case tea.KeyTab:
		a.completeHighlighted()
		return a, nil
	case tea.KeyShiftTab:
		return a, nil
	case tea.KeyUp:
		a.moveHighlight(-1)
		return a, nil
	case tea.KeyDown:
		a.moveHighlight(1)
		return a, nil
	case tea.KeyEnter:
		return a.runCommand()
	}
	return a.handleCommandInput(msg)
}

// handleCommandInput feeds an ordinary key to the input and ranks the registry
// again for the new text.
func (a *App) handleCommandInput(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd
	before := a.commandInput.Value()
	a.commandInput, cmd = a.commandInput.Update(msg)
	if a.commandInput.Value() != before {
		a.refreshSuggestions()
	}
	return a, cmd
}

// closeCommandLine leaves command mode and asks for the re-layout that gives
// the row back to the inactive prompt. The list goes with the line.
func (a *App) closeCommandLine() tea.Cmd {
	a.commandMode = false
	a.commandInput.Blur()
	a.resetSuggestions()
	return a.requestResize()
}

// runnableText is the single availability question for enter, read by the
// header (to grey it) and by runCommand (to refuse). With a list drawn it is
// the highlighted row's name. At the argument stage, or with no list drawn
// (too short a viewport), it is the text as typed: a prefix such as "co" is
// not a name and runs nothing, but an empty line has nothing to run.
func (a *App) runnableText() (string, bool) {
	if a.suggestions.Stage != command.StageArgument && a.listVisible() > 0 {
		entry, ok := a.highlightedEntry()
		return entry.Name, ok
	}
	input := a.commandInput.Value()
	return input, strings.TrimSpace(input) != ""
}

// runCommand executes the highlighted row, or at the argument stage the text
// as typed. With nothing to run it says so on the list's bottom rule and
// leaves the line open.
func (a *App) runCommand() (tea.Model, tea.Cmd) {
	input, ok := a.runnableText()
	if !ok {
		// Only a drawn list has a rule to carry the notice; without one the
		// refusal is silent, a documented exception to Rule 130.
		if a.listVisible() > 0 {
			a.sugNotice = a.nothingToRunNotice()
		}
		return a, nil
	}

	cmd := command.ParseCommand(input)

	switch cmd.Type {
	case command.CommandQuit:
		a.resetSuggestions()
		return a, tea.Quit

	case command.CommandView:
		a.commandMode = false
		a.commandInput.Blur()
		a.resetSuggestions()
		a.resetSelectionModeFor(cmd.View)
		return a, a.switchView(cmd.View)

	case command.CommandContext:
		return a.runContext(cmd.Args)
	}

	return a, nil
}

// resetSelectionModeFor takes a view out of selection mode before switching to
// it, by dropping it so it is rebuilt normally.
//
// Only the workspaces view is lent now. The images view was the other one — the
// security form borrowed it to pick a scan target — and it could not simply be
// dropped, because it holds scan results worth keeping; it took a
// ResetSelectionMsg instead. That whole path went with the form (phase 3).
//
// The security and network views are dropped too, when they are showing what
// another view sent them: workspaces and images set the security view's
// OriginView, and status's H sets netdiag's. What such a view shows is that
// view's detail, not its own state. Naming the view asks for the view — its
// inventory, or a blank form — and keeping the detail answered with the same
// thing again, with esc leading back to where it came from.
//
// A view reached by name has no origin and is kept, like every other view's
// state across a switch.
func (a *App) resetSelectionModeFor(view command.ViewType) {
	switch view {
	case command.ViewWorkspaces:
		delete(a.views, view)
	case command.ViewFiles:
		// A picker left behind — the user typed a command instead of choosing —
		// answers a borrower; the name asks for the browser.
		if held, ok := a.views[view].(filebrowser.Model); ok && held.Picking() {
			delete(a.views, view)
		}
	case command.ViewSecurity:
		if held, ok := a.views[view].(security.Model); ok && held.OriginView != "" {
			delete(a.views, view)
		}
	case command.ViewNetdiag:
		// The same rule, with one precaution the security view does not need: a
		// diagnostic sent from status may still be walking its stages, and
		// dropping the view would discard that run without a word. A run in
		// flight keeps its view; esc on it still returns to status.
		if held, ok := a.views[view].(*netdiag.Model); ok && held.OriginView != "" && !held.Running() {
			delete(a.views, view)
		}
	}
}

// switchView changes the current view
func (a *App) switchView(view command.ViewType) tea.Cmd {
	if view != a.currentView {
		if cmd, ok := a.settleCurrentView(); !ok {
			return cmd
		}
	}

	// Lazy loading of views
	if _, exists := a.views[view]; !exists {
		a.createView(view)
	}

	a.currentView = view

	newView, ok := a.views[view]
	if !ok {
		return nil
	}
	log.Printf("Switching to view: %s, calling Init()", view)

	// Init() + a WindowSizeMsg to force the resize, plus the snapshot of
	// work in progress: the view was kept up to date for as long as it
	// existed, but a view built just now was not there for anything that had
	// already started.
	return tea.Batch(newView.Init(), a.requestResize(), a.sendJobsTo(view))
}

// settleCurrentView gives the view being left the chance to write down what it
// holds, and lets it refuse to be left.
//
// A view that does not implement LeavingView is left without ceremony, which is
// every view but two: the configuration form keeps a value in a widget rather
// than in the model until a key moves the cursor, and the agent usage view has a
// live poll to stop.
//
// Returning false keeps the current view *and* whatever it wants to say about
// why — the caller passes that Cmd on rather than the switch it did not make.
func (a *App) settleCurrentView() (tea.Cmd, bool) {
	current, exists := a.views[a.currentView]
	if !exists {
		return nil, true
	}
	leaver, implements := current.(LeavingView)
	if !implements {
		return nil, true
	}
	settled, cmd, ok := leaver.Leave()
	a.views[a.currentView] = settled
	return cmd, ok
}

// createView creates a view (lazy loading)
func (a *App) createView(view command.ViewType) {
	if _, exists := a.views[view]; exists && view != command.ViewGitAuth {
		return
	}

	switch view {
	case command.ViewDashboard:
		a.views[view] = dashboard.New(a.config, a.sharedState)
	case command.ViewStatus:
		a.views[view] = status.New(a.config)
	case command.ViewGitAuth:
		a.views[view] = a.newAuthView()
	case command.ViewGitExplorer:
		a.views[view] = explorer.New(a.config, a.sharedState)
	case command.ViewWorkspaces:
		a.views[view] = workspaces.New(a.config, a.sharedState.Secrets.Storage)
	case command.ViewSecurity:
		a.views[view] = security.New(a.config, a.sharedState.Secrets.Storage)
	case command.ViewContainers:
		a.views[view] = containers.New(a.config)
	case command.ViewOCIResources:
		a.views[view] = ociresources.New(a.config)
	case command.ViewNetdiag:
		a.views[view] = netdiag.New(a.config)
	case command.ViewAgentUsage:
		a.views[view] = agentusageview.New(a.config)
	case command.ViewConfiguration:
		a.views[view] = configuration.New(a.config, a.mcpFacts())
	case command.ViewJobs:
		a.views[view] = jobsview.New(a.config, a.currentContext)
	case command.ViewTemplates:
		a.views[view] = templates.New(a.config, a.sharedState.Secrets.Storage)
	case command.ViewAbout:
		a.views[view] = about.New(a.config)
	case command.ViewFiles:
		a.views[view] = filebrowser.New(a.config)
	case command.ViewViewer:
		// Empty: the viewer is normally installed with its source by
		// handleViewerOpenRequest, and this case exists so the router can build
		// one like any other view — which is what the contract test does.
		a.views[view] = uiviewer.New(a.config)
	}
	// Built after the detection landed, it was not there to receive it.
	a.sendScanToolsTo(view)
}

// newAuthView builds the GitLab auth view against this context's credentials.
// It is rebuilt on every switch rather than cached, so the form reflects the
// session that is current now.
func (a *App) newAuthView() tea.Model {
	log.Printf("Creating GitLab auth view with context: %s", a.currentContext)

	authView := auth.New(a.config, a.sharedState.Secrets, a.sharedState.SecretNotices)
	if a.sharedState.IsAuthenticated {
		authView.SetAuth(a.sharedState.Forge, a.sharedState.CurrentUser)
	}
	return authView
}

