39	
40	// ASCII logo for the header
41	var logoLines = []string{
42		`    ____            ____            __  `,
43		`   / __ \___ _   __/ __ \___  _____/ /__`,
44		`  / / / / _ \ | / / / / / _ \/ ___/ //_/`,
45		` / /_/ /  __/ |/ / /_/ /  __(__  ) ,<   `,
46		`/_____/\___/|___/_____/\___/____/_/|_|  `,
47	}
48	
49	const logoWidth = 40 // max width of a logo line
50	
51	// renderHeader generates the header (fixed height) followed by the command line (1 line).
52	func (a *App) renderHeader() string {
53		if view, ok := a.views[a.currentView]; ok {
54			if headerView, implementsHeaderView := view.(HeaderView); implementsHeaderView {
55				shortcuts := headerView.GetShortcuts()
56				if a.commandMode {
57					shortcuts = a.commandLineShortcuts()
58				}
59				info := headerView.GetHeaderInfo(a.currentContext)
60	
61				header := renderHeaderContent(info, shortcuts, a.width)
62	
63				pad := theme.Bg(" ")
64				var cmdLine string
65				if a.commandMode {
66					cmdLine = pad + theme.CommandLineStyle.Width(a.width-2).Render(a.commandInput.View()) + pad
67				} else {
68					cmdLine = pad + theme.CommandLineInactiveStyle.Width(a.width-2).Render("❯") + pad
69				}
70	
71				// A blank line under the command line keeps it from touching the title rule.
72				return header + "\n" + theme.EmptyLineBg(a.width) + "\n" + cmdLine + "\n" + theme.EmptyLineBg(a.width)
73			}
74		}
75	
76		return ""
77	}
78	
79	// renderHeaderContent generates the header block with a fixed height (headerMinHeight).
80	// Layout: 3 columns — info (25%), shortcuts (flexible), logo (fixed width).
81	func renderHeaderContent(info []shortcut.HeaderInfo, shortcuts shortcut.Shortcuts, width int) string {
82		// Two padding cells are the minimum a row can hold; below that the header
83		// is blank rather than wider than the window.
84		if width < 2 {
85			return strings.Join(blankHeaderRows(width), "\n")
86		}
87		innerWidth := width - 2 // 1 padding each side
88	
89		// Column widths
90		col1Width := innerWidth / 4
91		col3Width := logoWidth
92		// The logo column is fixed-width: drop it when it cannot sit next to the
93		// info column, rather than pushing every row past the window (Rule 108).
94		if innerWidth < col1Width+logoWidth {
95			col3Width = 0
96		}
97		col2Width := innerWidth - col1Width - col3Width
98		if col2Width < 0 {
99			col2Width = 0
100		}
101	
102		// Build column 1: key-value info lines
103		col1Lines := buildInfoLines(info, col1Width)
104	
105		// Build column 2: shortcuts
106		col2Lines := buildShortcutLines(shortcuts, col2Width)
107	
108		// Build column 3: logo (centered vertically — 1 empty line on top since 6 logo lines / 7 header lines)
109		var col3Lines []string
110		if col3Width > 0 {
111			col3Lines = buildLogoLines(col3Width)
112		}
113	
114		// Assemble rows
115		rows := make([]string, headerMinHeight)
116		for i := 0; i < headerMinHeight; i++ {
117			c1 := ""
118			if i < len(col1Lines) {
119				c1 = col1Lines[i]
120			}
121			c2 := ""
122			if i < len(col2Lines) {
123				c2 = col2Lines[i]
124			}
125			c3 := ""
126			if i < len(col3Lines) {
127				c3 = col3Lines[i]
128			}
129	
130			pad := theme.Bg(" ")
131			row := pad + theme.PadWithBg(c1, col1Width) + theme.PadWithBg(c2, col2Width) + theme.PadWithBg(c3, col3Width) + pad
132			rows[i] = row
133		}
134	
135		return strings.Join(rows, "\n")
136	}
137	
138	// blankHeaderRows returns headerMinHeight background-filled rows of the given width.
139	func blankHeaderRows(width int) []string {
140		rows := make([]string, headerMinHeight)
141		for i := range rows {
142			rows[i] = theme.EmptyLineBg(width)
143		}
144		return rows
145	}
146	
147	// buildInfoLines builds the key-value info lines for column 1, aligning values on the longest key.
148	// Lines wider than col1Width are clipped, so a narrow column never overflows into the next one.
149	func buildInfoLines(info []shortcut.HeaderInfo, col1Width int) []string {
150		// Find max key length for alignment
151		maxKeyLen := 0
152		for _, h := range info {
153			if len(h.Key) > maxKeyLen {
154				maxKeyLen = len(h.Key)
155			}
156		}
157	
158		lines := make([]string, headerMinHeight)
159		for i := 0; i < headerMinHeight; i++ {
160			if i < len(info) {
161				// Pad key to maxKeyLen so all ": " align
162				paddedKey := info[i].Key + strings.Repeat(" ", maxKeyLen-len(info[i].Key))
163				label := theme.HeaderKeyStyle.Render(paddedKey + ": ")
164	
165				value := info[i].Value
166				if info[i].Style.GetForeground() != lipgloss.Color("") {
167					value = info[i].Style.Background(theme.ColorBackground).Render(value)
168				} else {
169					value = lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Render(value)
170				}
171	
172				lines[i] = label + value
173				if col1Width > 0 {
174					// MaxWidth truncates on rune boundaries and keeps escape sequences intact.
175					lines[i] = lipgloss.NewStyle().MaxWidth(col1Width).Render(lines[i])
176				} else {
177					// No room at all: show nothing rather than overflow.
178					lines[i] = ""
179				}
180			} else {
181				lines[i] = ""
182			}
183		}
184		return lines
185	}
186	
187	// buildShortcutLines builds the shortcut lines for column 2
188	func buildShortcutLines(shortcuts shortcut.Shortcuts, col2Width int) []string {
189		// A column with no width shows no shortcut: PadWithBg returns a long line
190		// untouched, so anything rendered here would spill past the window.
191		if len(shortcuts) == 0 || col2Width <= 0 {
192			lines := make([]string, headerMinHeight)
193			for i := range lines {
194				lines[i] = ""
195			}
196			return lines
197		}
198	
199		// Split shortcuts into columns of maxLine items
200		columns := splitArrayIntoChunks(shortcuts, headerMinHeight)
201	
202		// Get rendered lines for each column
203		var allColumnLines [][]string
204		for i, col := range columns {
205			minH := 0
206			if i == 0 {
207				minH = headerMinHeight
208			}
209			allColumnLines = append(allColumnLines, renderShortcutsColumnLines(col, minH))
210		}
211	
212		// Normalize heights
213		for i := range allColumnLines {
214			for len(allColumnLines[i]) < headerMinHeight {
215				allColumnLines[i] = append(allColumnLines[i], "")
216			}
217		}
218	
219		// Calculate column widths
220		colWidths := make([]int, len(allColumnLines))
221		for ci, colLines := range allColumnLines {
222			for _, line := range colLines {
223				if w := lipgloss.Width(line); w > colWidths[ci] {
224					colWidths[ci] = w
225				}
226			}
227		}
228	
229		sep := "  "
230		sepRendered := theme.Bg(sep)
231	
232		// Build each row
233		result := make([]string, headerMinHeight)
234		for row := 0; row < headerMinHeight; row++ {
235			var line string
236			for ci, colLines := range allColumnLines {
237				if ci > 0 {
238					line += sepRendered
239				}
240				if row < len(colLines) {
241					line += theme.PadWithBg(colLines[row], colWidths[ci])
242				} else {
243					line += theme.EmptyLineBg(colWidths[ci])
244				}
245			}
246			// Clip to the column. PadWithBg cannot do this — it pads a short line and
247			// returns a long one untouched — and a plain slice would cut an escape
248			// sequence in half, which is the hazard Rule 122 is about. MaxWidth
249			// truncates on rune boundaries and leaves the sequences intact.
250			if col2Width > 0 {
251				line = lipgloss.NewStyle().MaxWidth(col2Width).Render(line)
252			}
253			result[row] = line
254		}
255	
256		return result
257	}
258	
259	// buildLogoLines builds the logo lines for column 3, vertically centered
260	func buildLogoLines(col3Width int) []string {
261		logoStyle := lipgloss.NewStyle().
262			Background(theme.ColorBackground).
263			Foreground(theme.ColorPrimary).
264			Bold(true)
265	
266		lines := make([]string, headerMinHeight)
267		// 5 logo lines in 7 header lines → 1 empty line top and bottom
268		offset := 1
269		for i := 0; i < headerMinHeight; i++ {
270			logoIdx := i - offset
271			if logoIdx >= 0 && logoIdx < len(logoLines) {
272				lines[i] = theme.PadWithBg(logoStyle.Render(logoLines[logoIdx]), col3Width)
273			} else {
274				lines[i] = theme.EmptyLineBg(col3Width)
275			}
276		}
277		return lines
278	}
279	
280	// renderShortcutsColumnLines renders a column of shortcuts as individual lines padded to the same width with background.
281	func renderShortcutsColumnLines(shortcuts shortcut.Shortcuts, minHeight int) []string {
282		if len(shortcuts) == 0 {
283			return nil
284		}
285	
286		lines := shortcuts.ToStrings()
287	
288		// Find max width for uniform padding
289		maxWidth := 0
290		for _, line := range lines {
291			if w := lipgloss.Width(line); w > maxWidth {
292				maxWidth = w
293			}
294		}
295	
296		// Pad each line to the same width with background
297		var result []string
298		for _, line := range lines {
299			result = append(result, theme.PadWithBg(line, maxWidth))
300		}
301	
302		// Add empty lines if minHeight required
303		for len(result) < minHeight {
304			result = append(result, theme.EmptyLineBg(maxWidth))
305		}
306	
307		return result
308	}
309	
310	func splitArrayIntoChunks(arr []shortcut.Shortcut, chunkSize int) []shortcut.Shortcuts {
311		var chunks []shortcut.Shortcuts
312		for i := 0; i < len(arr); i += chunkSize {
313			end := i + chunkSize
314			if end > len(arr) {
315				end = len(arr)
316			}
317			chunks = append(chunks, arr[i:end])
318		}
319		return chunks
320	}
321	
322	// commandLineShortcuts is the header's vocabulary while the command line owns
323	// the keyboard. It replaces the view's own: tab and enter stay in place and
324	// grey out when no row is highlighted (Rule 130).
325	func (a *App) commandLineShortcuts() shortcut.Shortcuts {
326		_, runnable := a.runnableText()
327		return shortcut.Shortcuts{
328			{Key: "↑↓", Description: "Choose"},
329			{Key: "tab", Description: "Complete", Disabled: !a.canComplete()},
330			{Key: "enter", Description: "Open", Disabled: !runnable},
331			{Key: "esc", Description: "Close"},
332		}
333	}
