package app

import (
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/contextcmd"
	"github.com/anthnel/devdesk/internal/ui/cmdsuggest"
	"github.com/anthnel/devdesk/internal/ui/components"
)

// argStage reports whether the list shows argument rows: the :ctx command at
// its argument stage. Other commands keep the single command row.
func (a *App) argStage() bool {
	return a.suggestions.Stage == command.StageArgument &&
		command.ParseCommand(a.commandInput.Value()).Type == command.CommandContext
}

// listRowCount is how many rows the list holds at the current stage.
func (a *App) listRowCount() int {
	if a.argStage() {
		return len(a.suggestions.Args)
	}
	return len(a.suggestions.Entries)
}

// ctxArgText is the text typed after the command word, trimmed on the left.
func (a *App) ctxArgText() string {
	_, rest, _ := strings.Cut(strings.TrimLeft(a.commandInput.Value(), ": "), " ")
	return strings.TrimLeft(rest, " ")
}

// defaultArgCursor picks the row highlighted when the argument list is drawn:
// the exact match; else the only match when contextcmd accepts it as a valid
// name; else none.
func (a *App) defaultArgCursor() int {
	args := a.suggestions.Args
	prefix := a.ctxArgText()
	if prefix == "" || !a.suggestions.ArgsReady {
		return -1
	}
	for i, s := range args {
		if s.Value == prefix {
			return i
		}
	}
	if len(args) != 1 {
		return -1
	}
	if !contextcmd.ValidName(prefix) {
		return -1
	}
	return 0
}

// argHeading is the rule's label at the argument stage: contexts shown out of
// all contexts, the reserved words not counted.
func (a *App) argHeading() string {
	shown := 0
	for _, s := range a.suggestions.Args {
		if s.Value != contextcmd.WordPrevious && s.Value != contextcmd.WordNew {
			shown++
		}
	}
	return fmt.Sprintf("Contexts · %d of %d", shown, len(a.snapshot().Names))
}

// argRows renders the argument suggestions as list rows.
func (a *App) argRows() []cmdsuggest.Row {
	rows := make([]cmdsuggest.Row, len(a.suggestions.Args))
	for i := range a.suggestions.Args {
		s := a.suggestions.Args[i]
		rows[i] = cmdsuggest.Row{Arg: &s, Current: s.Current}
	}
	return rows
}

// argEmpty is the message of an argument list with no rows.
func (a *App) argEmpty() string {
	prefix := a.ctxArgText()
	if strings.HasPrefix(strings.ToLower(prefix), contextcmd.WordNew+" ") {
		return ""
	}
	return fmt.Sprintf("No context starts with %q", prefix)
}

// highlightedArg returns the value of the highlighted argument row, or "".
func (a *App) highlightedArg() string {
	if !a.argStage() || a.sugCursor < 0 || a.sugCursor >= len(a.suggestions.Args) {
		return ""
	}
	return a.suggestions.Args[a.sugCursor].Value
}

// completeArg is tab at the argument stage: it highlights the first row when
// none is, otherwise writes the highlighted value into the line.
func (a *App) completeArg() {
	if len(a.suggestions.Args) == 0 {
		return
	}
	if a.sugCursor < 0 {
		a.sugCursor = a.sugOffset
		return
	}
	word, _, _ := strings.Cut(strings.TrimLeft(a.commandInput.Value(), ": "), " ")
	text := word + " " + a.highlightedArg()
	if a.highlightedArg() == contextcmd.WordNew {
		text += " "
	}
	a.commandInput.SetValue(text)
	a.commandInput.CursorEnd()
	a.refreshSuggestions()
}

// runContext is enter on a :ctx command line.
func (a *App) runContext(args []string) (tea.Model, tea.Cmd) {
	highlighted := a.highlightedArg()
	if highlighted == contextcmd.WordNew && (len(args) == 0 || args[0] != contextcmd.WordNew) {
		// "new" takes an argument of its own: enter completes it like tab.
		a.completeArg()
		return a, nil
	}
	if highlighted == contextcmd.WordPrevious {
		args = []string{highlighted}
	}
	if len(args) == 0 && highlighted != "" {
		args = []string{highlighted}
	}
	action := contextcmd.Resolve(args, highlighted, a.snapshot())
	if action.Kind == contextcmd.KeepOpen {
		a.sugNotice = action.Text
		return a, nil
	}
	a.closeCommandLineQuiet()
	switch action.Kind {
	case contextcmd.Switch:
		return a, a.switchContext(action.Name)
	case contextcmd.Create:
		return a, a.createContext(action.Name)
	case contextcmd.Refuse:
		return a, components.PostFooter(footerLevel(action.Level), action.Text)
	}
	return a, a.listContexts()
}

// closeCommandLineQuiet leaves command mode; the caller returns the Cmd that
// follows (the re-layout happens on the next resize).
func (a *App) closeCommandLineQuiet() {
	a.commandMode = false
	a.commandInput.Blur()
	a.resetSuggestions()
}

// footerLevel maps a contextcmd level to a footer level.
func footerLevel(l contextcmd.Level) components.Level {
	switch l {
	case contextcmd.Warn:
		return components.LevelWarning
	case contextcmd.Error:
		return components.LevelError
	}
	return components.LevelInfo
}

type FilterBarView interface {
	FilterBarVisible() bool
}

// App is the main model, with a multi-view router
type App struct {
	config         *config.Config
	currentContext string
	// previousContext is the context left by the last switch, "" before any.
	previousContext string
	// ctxArgs is the snapshot behind the :ctx argument suggestions.
	ctxArgs  *contextArgs
	viewport viewport.Model

	// Navigation
	currentView command.ViewType
	views       map[command.ViewType]tea.Model
	sharedState *shared.State

	commandMode  bool
	commandInput textinput.Model

	// Command suggestions (DEVDESK-89): the list drawn over the viewport while
	// the command line is open.
	suggester   *command.Suggester
	suggestions command.Suggestions
	// sugCursor is the highlighted row, or -1 when none is.
	sugCursor int
	sugOffset int // first row drawn when the list scrolls
	// sugNotice is the warning on the list's bottom rule. It lasts until the
	// next key, with no timer.
	sugNotice string

	// Context list overlay
	showContextList    bool
	contextList        []string
	contextSelectedIdx int
	// switchingTo names the context a switch is loading, or "" when none is.
	// While it is set the previous context's interface is not drawn: the load
	// includes a network login, and showing the old views for its duration
	// read as the new context appearing first and switching afterwards.
	switchingTo string

	// Help overlay
	showHelp     bool
	helpViewport viewport.Model

	// Selection mode (cross-view browsing)
	selectionReturnView command.ViewType // View to return to after selection
	// selectionLent is the view built in selection mode for that borrower. It is
	// what leaveSelectionMode drops so the view is rebuilt normally, and it is
	// not always the same one: workspaces for a directory, templates for a
	// template.
	selectionLent command.ViewType
	// pickerReturnView is the view a lent path picker answers (picker.go).
	pickerReturnView command.ViewType

	// Long-running work. The registry is the one bookkeeping of what is
	// running (internal/jobs); the router owns it, and owns the single spinner
	// chain that animates it (D5). Views read a snapshot carried in
	// JobsChangedMsg — see jobs.go.
	jobs *jobs.Registry
	// The one detection of the scanners — see scan_tools.go.
	toolsState
	forgeIndexState
	jobFrameIdx int
	jobTickSeq  int
	jobTicking  bool

	// The MCP server, which lives in this process (§3.61). program is the
	// handle a request needs to reach Update() — set once by AttachProgram,
	// before the loop starts — and the three fields below are what became of
	// the attempt to serve: a running server, the address it actually bound, or
	// the reason there is none. `mcp.enabled: false` is one of those reasons
	// rather than the absence of one.
	program     *tea.Program
	mcpDispatch mcpDispatcher
	mcpServer   *http.Server
	mcpToken    string
	// mcpEpoch numbers the starts, so a report from one the session has moved
	// past is recognised and its listener closed rather than stored.
	mcpEpoch uint64

	// forwardStore is where the forwards are kept between launches (§3.75). It
	// is nil until New sets it, so a router built by a test never writes to the
	// developer's own ~/.devdesk.
	forwardStore *forward.Store

	// wantedProxyPort is the port named routes should be served on, written
	// from Update and read by the Cmd that moves the proxy. Two moves can be in
	// flight — a config saved twice quickly — and each one applies the value as
	// it is when it runs, so whichever finishes last leaves the proxy on the
	// latest port and not on a stale one.
	wantedProxyPort atomic.Int64
	// pendingInvocations holds the reply channel of every action call waiting
	// for the identifier of the run it asked for. Mutated from Update alone,
	// like everything else here.
	pendingInvocations map[invocationID]chan mcpStartReply
	mcpAddr            string
	mcpErr             error

	// Dimensions
	width            int
	height           int
	lastFooterHeight int // tracks current view's footer height for re-resize detection
}

func newCommandInput() textinput.Model {
	// Create the input for command mode
	cmdInput := textinput.New()
	cmdInput.Prompt = "❯"
	cmdInput.CharLimit = 50

	return cmdInput
}

func newViewport(width, height int) viewport.Model {
	vp := viewport.New(width, height)
	vp.Style = viewportStyle()
	return vp
}

func viewportStyle() lipgloss.Style {
	return lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorText).
		Border(lipgloss.NormalBorder(), false, true, true, true).
		BorderForeground(theme.ColorViewportBorder).
		BorderBackground(theme.ColorBackground)
}

// framelessViewportStyle is the viewport style for a view that draws its own
// frames (FramelessView): same background, no border.
func framelessViewportStyle() lipgloss.Style {
	return lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorText)
}

// New creates a new App, sized to the current terminal.
func New(cfg *config.Config) *App {
	width, height, err := term.GetSize(os.Stdout.Fd())
	if err != nil {
		panic(err)
	}
	app := newWithSize(cfg, width, height)
	app.useSecrets(credentials.Select(app.currentContext, cfg.App.SecretBackend))
	// Resolved here rather than in newWithSize for the same reason as the
	// secret store: it runs exec.LookPath, and a constructor that reaches for
	// the machine is one tests cannot run twice the same way.
	app.resolveContainerEngine()
	app.useForwardStore()
	return app
}

// useSecrets points the router at a resolved secret store and sweeps whatever
// plaintext an earlier version left in this context's configuration file.
//
// It is separate from newWithSize because resolving a backend is I/O — a probe
// of the host store and a read of git's configuration — and a constructor that
// reaches for the machine's keyring is one tests cannot run twice the same way.
func (a *App) useSecrets(sel credentials.Selection) {
	a.sharedState.Secrets = sel
	a.sharedState.SecretNotices = credentials.MigrateLegacySecrets(sel.Storage, a.currentContext)
	log.Printf("Secret backend for context %q: %s", a.currentContext, sel.Backend)

	// The auth view holds the storage it was built with, so rebuild it if it
	// already exists. Every other view reaches secrets through the router.
	if _, ok := a.views[command.ViewGitAuth]; ok {
		a.views[command.ViewGitAuth] = a.newAuthView()
	}
}

// newWithSize builds the router at a given size. New() reads that size from the
// terminal; splitting it out keeps the constructor itself free of I/O.
func newWithSize(cfg *config.Config, width, height int) *App {
	currentContext, _ := config.GetCurrentContext()

	// A store is always present: views never have to test for nil.
	// New() replaces this one with the real backend via useSecrets.
	sharedState := &shared.State{
		Secrets: credentials.SessionOnly("no secret store has been resolved yet"),
		// Created here and never replaced: the forwards outlive every view
		// rebuild, and a context switch with them (§3.1).
		Forwards: forward.New(),
	}
	// Telling the registry which port is not I/O — nothing is serving yet, so
	// nothing is bound — and a route opened before the first Cmd needs to know.
	_ = sharedState.Forwards.SetProxyPort(cfg.Network.ProxyPort)

	app := &App{
		config:         cfg,
		currentContext: currentContext,
		viewport:       newViewport(width, height),
		currentView:    defaultView(cfg),
		views:          make(map[command.ViewType]tea.Model),
		sharedState:    sharedState,
		jobs:           jobs.New(),
		commandInput:   newCommandInput(),
		suggester:      command.NewSuggester(),
		sugCursor:      -1,
		width:          width,
		height:         height,
	}
	app.ctxArgs = &contextArgs{}
	app.suggester.WithProvider("context", app.ctxArgs)
	app.wantedProxyPort.Store(int64(cfg.Network.ProxyPort))

	// Other views are created on demand (lazy loading).
	app.createView(command.ViewDashboard)
	app.createView(command.ViewStatus)
	app.createView(app.currentView)

	// Computes the available height and propagates it to the views.
	app.resize(width, height)

	return app
}

// defaultView resolves the configured landing view, falling back to the
// dashboard when the setting is missing or unparseable.
func defaultView(cfg *config.Config) command.ViewType {
	if cfg.App.DefaultView == "" {
		return command.ViewDashboard
	}
	parsed, err := command.Parse(cfg.App.DefaultView)
	if err != nil || parsed == "" {
		return command.ViewDashboard
	}
	return parsed
}

// AttachProgram gives the router the handle an MCP request needs to reach
// Update().
//
// It is called by main() between tea.NewProgram and p.Run(), which is the only
// window where writing a field of the model is safe outside Update: the loop
// has not started, so there is nothing to race with. Anything that needs the
// program later reads it; nothing writes it again.
func (a *App) AttachProgram(p *tea.Program) {
	a.program = p
	a.mcpDispatch = mcpDispatcher{program: p}
}

// Init initializes the application
func (a *App) Init() tea.Cmd {
	// Note: resize() is already called in newWithSize() to initialize the dimensions
	cmds := []tea.Cmd{a.tryAutoLogin(), a.startMCPCmd(), a.restoreForwardsCmd(), a.detectScanTools()}

	if view, ok := a.views[a.currentView]; ok {
		cmds = append(cmds, view.Init())
	}

	return tea.Batch(cmds...)
}

// requestResize asks for a fresh layout at the current size. Every handler that
// changes what the window holds returns one, because the viewport height is
// budgeted against the header and the active view's footer.
func (a *App) requestResize() tea.Cmd {
	return func() tea.Msg {
		return tea.WindowSizeMsg{Width: a.width, Height: a.height}
	}
}

// resize lays out the window. It **iterates**, and that is necessary: the
// footer height is asked of the view (Rule 124), but a view whose footer
// depends on its own size — the dashboard hides its tab line once only one
// remains — answers based on the size it had *before*. A single pass would
// therefore leave it off by one line until the next resize.
// Two passes are enough: the second queries a view that now knows its size.
func (a *App) resize(width, height int) {
	a.width = width
	a.height = height
	defer a.keepHighlightVisible()

	const passes = 2
	for range passes {
		if !a.layoutOnce(width, height) {
			return
		}
	}
}

// layoutOnce sizes the viewport against the active view's footer and hands the
// view its content height. It returns true when the footer height changed
// along the way, i.e. when a second pass says something different.
func (a *App) layoutOnce(width, height int) (changed bool) {
	// Rule 124: footer height is deducted from the viewport (tabs + optional info line)
	footerHeight := a.getFooterHeight()
	a.lastFooterHeight = footerHeight

	headerHeight := lipgloss.Height(a.renderHeader())
	availableHeight := height - headerHeight - footerHeight
	a.viewport.Width = width
	a.viewport.Height = availableHeight - 1 // -1 for the custom title border line

	// Propagate to the active view. The viewport has 1 border (bottom only),
	// the view must know the inner height. A frameless view has none and
	// reclaims the line.
	viewportBorderHeight := 1
	a.viewport.Style = viewportStyle()
	if a.frameless() {
		viewportBorderHeight = 0
		a.viewport.Style = framelessViewportStyle()
	}
	contentHeight := max((availableHeight-1)-viewportBorderHeight, 1)
	if view, ok := a.views[a.currentView]; ok {
		updatedView, _ := view.Update(tea.WindowSizeMsg{Width: width, Height: contentHeight})
		a.views[a.currentView] = updatedView
	}

	return a.getFooterHeight() != footerHeight
}

// getFooterHeight returns the current footer height for the active view.
func (a *App) getFooterHeight() int {
	if view, ok := a.views[a.currentView]; ok {
		if fv, ok := view.(FooterView); ok {
			return fv.GetFooterHeight()
		}
	}
	return 0
}

// reinitializeViews drops every view so they are rebuilt against the current
// config, and returns the init cmd for the one on screen.
func (a *App) reinitializeViews() tea.Cmd {
	log.Printf("Reinitializing views with new config")
	a.views = make(map[command.ViewType]tea.Model)
	a.createView(a.currentView)

	var initCmd tea.Cmd
	if view, ok := a.views[a.currentView]; ok {
		initCmd = view.Init()
	}
	log.Printf("Views reinitialized successfully")
	return initCmd
}

