15	// argStage reports whether the list shows argument rows: the :ctx command at
16	// its argument stage. Other commands keep the single command row.
17	func (a *App) argStage() bool {
18		return a.suggestions.Stage == command.StageArgument &&
19			command.ParseCommand(a.commandInput.Value()).Type == command.CommandContext
20	}
21	
22	// listRowCount is how many rows the list holds at the current stage.
23	func (a *App) listRowCount() int {
24		if a.argStage() {
25			return len(a.suggestions.Args)
26		}
27		return len(a.suggestions.Entries)
28	}
29	
30	// ctxArgText is the text typed after the command word, trimmed on the left.
31	func (a *App) ctxArgText() string {
32		_, rest, _ := strings.Cut(strings.TrimLeft(a.commandInput.Value(), ": "), " ")
33		return strings.TrimLeft(rest, " ")
34	}
35	
36	// defaultArgCursor picks the row highlighted when the argument list is drawn:
37	// the exact match; else the only match when contextcmd accepts it as a valid
38	// name; else none.
39	func (a *App) defaultArgCursor() int {
40		args := a.suggestions.Args
41		prefix := a.ctxArgText()
42		if prefix == "" || !a.suggestions.ArgsReady {
43			return -1
44		}
45		for i, s := range args {
46			if s.Value == prefix {
47				return i
48			}
49		}
50		if len(args) != 1 {
51			return -1
52		}
53		if !contextcmd.ValidName(prefix) {
54			return -1
55		}
56		return 0
57	}
58	
59	// argHeading is the rule's label at the argument stage: contexts shown out of
60	// all contexts, the reserved words not counted.
61	func (a *App) argHeading() string {
62		shown := 0
63		for _, s := range a.suggestions.Args {
64			if s.Value != contextcmd.WordPrevious && s.Value != contextcmd.WordNew {
65				shown++
66			}
67		}
68		return fmt.Sprintf("Contexts · %d of %d", shown, len(a.snapshot().Names))
69	}
70	
71	// argRows renders the argument suggestions as list rows.
72	func (a *App) argRows() []cmdsuggest.Row {
73		rows := make([]cmdsuggest.Row, len(a.suggestions.Args))
74		for i := range a.suggestions.Args {
75			s := a.suggestions.Args[i]
76			rows[i] = cmdsuggest.Row{Arg: &s, Current: s.Current}
77		}
78		return rows
79	}
80	
81	// argEmpty is the message of an argument list with no rows.
82	func (a *App) argEmpty() string {
83		prefix := a.ctxArgText()
84		if strings.HasPrefix(strings.ToLower(prefix), contextcmd.WordNew+" ") {
85			return ""
86		}
87		return fmt.Sprintf("No context starts with %q", prefix)
88	}
89	
90	// highlightedArg returns the value of the highlighted argument row, or "".
91	func (a *App) highlightedArg() string {
92		if !a.argStage() || a.sugCursor < 0 || a.sugCursor >= len(a.suggestions.Args) {
93			return ""
94		}
95		return a.suggestions.Args[a.sugCursor].Value
96	}
97	
98	// completeArg is tab at the argument stage: it highlights the first row when
99	// none is, otherwise writes the highlighted value into the line.
100	func (a *App) completeArg() {
101		if len(a.suggestions.Args) == 0 {
102			return
103		}
104		if a.sugCursor < 0 {
105			a.sugCursor = a.sugOffset
106			return
107		}
108		word, _, _ := strings.Cut(strings.TrimLeft(a.commandInput.Value(), ": "), " ")
109		text := word + " " + a.highlightedArg()
110		if a.highlightedArg() == contextcmd.WordNew {
111			text += " "
112		}
113		a.commandInput.SetValue(text)
114		a.commandInput.CursorEnd()
115		a.refreshSuggestions()
116	}
117	
118	// runContext is enter on a :ctx command line.
119	func (a *App) runContext(args []string) (tea.Model, tea.Cmd) {
120		highlighted := a.highlightedArg()
121		if highlighted == contextcmd.WordNew && (len(args) == 0 || args[0] != contextcmd.WordNew) {
122			// "new" takes an argument of its own: enter completes it like tab.
123			a.completeArg()
124			return a, nil
125		}
126		if highlighted == contextcmd.WordPrevious {
127			args = []string{highlighted}
128		}
129		if len(args) == 0 && highlighted != "" {
130			args = []string{highlighted}
131		}
132		action := contextcmd.Resolve(args, highlighted, a.snapshot())
133		if action.Kind == contextcmd.KeepOpen {
134			a.sugNotice = action.Text
135			return a, nil
136		}
137		a.closeCommandLineQuiet()
138		switch action.Kind {
139		case contextcmd.Switch:
140			return a, a.switchContext(action.Name)
141		case contextcmd.Create:
142			return a, a.createContext(action.Name)
143		case contextcmd.Refuse:
144			return a, components.PostFooter(footerLevel(action.Level), action.Text)
145		}
146		return a, a.listContexts()
147	}
148	
149	// closeCommandLineQuiet leaves command mode; the caller returns the Cmd that
150	// follows (the re-layout happens on the next resize).
151	func (a *App) closeCommandLineQuiet() {
152		a.commandMode = false
153		a.commandInput.Blur()
154		a.resetSuggestions()
155	}
156	
157	// footerLevel maps a contextcmd level to a footer level.
158	func footerLevel(l contextcmd.Level) components.Level {
159		switch l {
160		case contextcmd.Warn:
161			return components.LevelWarning
162		case contextcmd.Error:
163			return components.LevelError
164		}
165		return components.LevelInfo
166	}
