1	package app
2	
3	import (
4		"fmt"
5		"strings"
6		"testing"
7	
8		tea "github.com/charmbracelet/bubbletea"
9		"github.com/charmbracelet/lipgloss"
10		"github.com/charmbracelet/x/ansi"
11	
12		"github.com/anthnel/devdesk/internal/command"
13		"github.com/anthnel/devdesk/internal/ui/testutil"
14	)
15	
16	// DEVDESK-89 step 7 (DEVDESK-108): the command line and its suggestion list
17	// keep the layout whole at awkward sizes, on both frames, and across resizes.
18	
19	// framelessFake is a fakeView that draws its own frames, like the dashboard.
20	type framelessFake struct{ fakeView }
21	
22	func (*framelessFake) Frameless() bool { return true }
23	
24	// Update keeps the wrapper in the router's map; the promoted one would hand
25	// back the inner fakeView and lose Frameless.
26	func (v *framelessFake) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
27		_, cmd := v.fakeView.Update(msg)
28		return v, cmd
29	}
30	
31	// resizeTo feeds a terminal resize through Update, as bubbletea would.
32	func resizeTo(t *testing.T, a *App, w, h int) {
33		t.Helper()
34		a.Update(tea.WindowSizeMsg{Width: w, Height: h})
35	}
36	
37	// tinyHeights are terminal heights where the viewport has less than 2 usable
38	// lines for a list (header 10 + title 1 + viewport; a framed view keeps its bottom border).
39	var tinyHeights = []int{13, 12, 11}
40	
41	// ── Usable height under 2: no list, the line stays usable ────────────────────
42	
43	func TestNoListWhenTheViewportIsTooShortButTheLineStaysUsable(t *testing.T) {
44		for _, h := range tinyHeights {
45			t.Run(fmt.Sprintf("80x%d", h), func(t *testing.T) {
46				a := routerAt(t, &fakeView{body: "body"}, 80, h)
47				press(t, a, "ctrl+p")
48				typeCommand(t, a, "co")
49	
50				if got := a.commandInput.Value(); got != "co" {
51					t.Errorf("typed text = %q, want co: the line is not usable", got)
52				}
53				if i := filetIndex(screen(a)); i >= 0 {
54					t.Errorf("a list rule is drawn at line %d with no room for a list", i)
55				}
56				if got := lipgloss.Height(a.View()); got != h {
57					t.Errorf("View is %d lines, want %d", got, h)
58				}
59			})
60		}
61	}
62	
63	// Decision (see the report): with no list on screen there is no choice to
64	// make, so enter runs the text as typed, like the argument stage. A prefix is
65	// not a name: "co" runs nothing rather than opening a view nobody saw.
66	func TestEnterNeverOpensAnInvisibleChoiceWhenThereIsNoList(t *testing.T) {
67		for _, h := range tinyHeights {
68			t.Run(fmt.Sprintf("80x%d", h), func(t *testing.T) {
69				a := routerAt(t, &fakeView{body: "body"}, 80, h)
70				press(t, a, "ctrl+p")
71				typeCommand(t, a, "co")
72				press(t, a, "enter")
73	
74				if a.currentView != command.ViewDashboard || !a.commandMode {
75					t.Errorf("view=%s commandMode=%v: enter opened a choice nobody could see", a.currentView, a.commandMode)
76				}
77				if _, ok := a.highlightedEntry(); ok {
78					t.Error("a row is highlighted while no list is drawn")
79				}
80			})
81		}
82	}
83	
84	func TestEnterRunsTheExactTypedNameWhenThereIsNoList(t *testing.T) {
85		a := routerAt(t, &fakeView{body: "body"}, 80, 12)
86		press(t, a, "ctrl+p")
87		typeCommand(t, a, "containers")
88		press(t, a, "enter")
89	
90		if a.currentView != command.ViewContainers || a.commandMode {
91			t.Errorf("view=%s commandMode=%v, want containers with the line closed", a.currentView, a.commandMode)
92		}
93	}
94	
95	func TestEnterOnAnEmptyLineWithNoListChangesNothing(t *testing.T) {
96		a := routerAt(t, &fakeView{body: "body"}, 80, 12)
97		press(t, a, "ctrl+p")
98		cmd := press(t, a, "enter")
99	
100		if _, quit := testutil.MsgOf[tea.QuitMsg](cmd); quit {
101			t.Fatal("enter on an empty line quit the application")
102		}
103		if a.currentView != command.ViewDashboard || !a.commandMode {
104			t.Errorf("view=%s commandMode=%v: the empty enter acted", a.currentView, a.commandMode)
105		}
106	}
107	
108	func TestEscStillClosesTheLineWhenThereIsNoList(t *testing.T) {
109		a := routerAt(t, &fakeView{body: "body"}, 80, 12)
110		press(t, a, "ctrl+p")
111		typeCommand(t, a, "co")
112		press(t, a, "esc")
113		if a.commandMode {
114			t.Error("esc left the command line open")
115		}
116	}
117	
118	// ── Height of View() without a list, and with a short terminal ───────────────
119	
120	func TestViewHeightIsTheTerminalsWithTheLineClosedOrListless(t *testing.T) {
121		sizes := [][2]int{{80, 24}, {120, 40}, {60, 30}, {40, 16}, {40, 8}, {80, 6}}
122		for _, sz := range sizes {
123			t.Run(fmt.Sprintf("%dx%d/closed", sz[0], sz[1]), func(t *testing.T) {
124				a := routerAt(t, &fakeView{body: "body"}, sz[0], sz[1])
125				if h := lipgloss.Height(a.View()); h != sz[1] {
126					t.Errorf("View is %d lines, want %d", h, sz[1])
127				}
128			})
129			t.Run(fmt.Sprintf("%dx%d/open", sz[0], sz[1]), func(t *testing.T) {
130				a := routerAt(t, &fakeView{body: "body"}, sz[0], sz[1])
131				press(t, a, "ctrl+p")
132				typeCommand(t, a, "co")
133				if h := lipgloss.Height(a.View()); h != sz[1] {
134					t.Errorf("View is %d lines, want %d", h, sz[1])
135				}
136			})
137		}
138	}
139	
140	// ── Frames ───────────────────────────────────────────────────────────────────
141	
142	func TestAFramelessViewKeepsItsSidesAndClosesTheRule(t *testing.T) {
143		a := routerAt(t, &framelessFake{fakeView{body: "body"}}, 80, 30)
144		press(t, a, "ctrl+p")
145		typeCommand(t, a, "co")
146	
147		lines := screen(a)
148		var rule = -1
149		for i, l := range lines {
150			if strings.HasPrefix(l, "└") && strings.HasSuffix(l, "┘") {
151				rule = i
152				break
153			}
154		}
155		if rule < 0 {
156			t.Fatalf("no closed └…┘ rule:\n%s", strings.Join(lines, "\n"))
157		}
158		if filetIndex(lines) >= 0 {
159			t.Error("a joined ├…┤ rule is drawn on a frameless view")
160		}
161		// The rows sit above the rule, after the title rule, and carry their sides.
162		n := 0
163		for i := rule - 1; i >= 0 && strings.HasPrefix(lines[i], "│"); i-- {
164			if !strings.HasSuffix(lines[i], "│") {
165				t.Errorf("row %q lacks its right side", lines[i])
166			}
167			n++
168		}
169		if n == 0 {
170			t.Errorf("no row with │ sides above the rule:\n%s", strings.Join(lines, "\n"))
171		}
172		if got := lipgloss.Height(a.View()); got != 30 {
173			t.Errorf("View is %d lines, want 30", got)
174		}
175	}
176	
177	func TestAFramedViewClosesTheRuleWithTJunctions(t *testing.T) {
178		a := routerAt(t, &fakeView{body: "body"}, 80, 30)
179		press(t, a, "ctrl+p")
180		typeCommand(t, a, "co")
181	
182		r := filet(t, a)
183		if !strings.HasPrefix(r, "├") || !strings.HasSuffix(r, "┤") {
184			t.Errorf("rule %q is not ├…┤", r)
