			}
			all := strings.Join(lines, "\n")
			header := strings.Join(lines[:10], "\n")
			if !strings.Contains(header, "co") {
				t.Errorf("the command line is cut off:\n%s", all)
			}
			if !strings.Contains(all, "FOOTERINFO") {
				t.Errorf("the footer is cut off:\n%s", all)
			}
		})
	}
}

